<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {useI18n} from 'vue-i18n';
import {useDashboard,isPublicDemo} from '../stores/dashboard';
import {usePlanning} from '../stores/planning';
import {validDate,weekEnd} from '../planning';
import {recipeLabel,ingredientLabel} from '../recipe-labels';
const account=useDashboard();const store=usePlanning();const {t,locale,te}=useI18n();
const from=ref(account.data!.date);const date=ref(from.value);const recipe=ref(account.data!.recommendations[0]?.slug??'');const portions=ref(3);const pending=ref(false);const notice=ref('');const failure=ref('');const copyText=ref('');const to=computed(()=>validDate(from.value)?weekEnd(from.value):'');
watch([from,()=>account.token,()=>account.sessionVersion],()=>{notice.value='';copyText.value='';store.clear();if(validDate(from.value)&&(isPublicDemo||account.token))void store.refresh(from.value,to.value);},{immediate:true});
async function add(){const session=account.sessionVersion;pending.value=true;failure.value='';try{await store.add({recipe_slug:recipe.value,servings:Number(portions.value),planned_for:date.value});if(session!==account.sessionVersion)return;from.value=date.value;await store.refresh(from.value,to.value);notice.value='planSaved';}catch(e){failure.value=e instanceof Error&&te(e.message)?e.message:'planningFailed';}finally{pending.value=false;}}
async function remove(id:number){const session=account.sessionVersion;pending.value=true;failure.value='';try{await store.remove(id);if(session!==account.sessionVersion)return;await store.refresh(from.value,to.value);notice.value='planRemoved';}catch{failure.value='planningFailed';}finally{pending.value=false;}}
async function copy(){const value=(store.shopping?.items??[]).map(i=>`${ingredientLabel(i.name,locale.value)} · ${i.grams} ${t('grams')} (${i.preparation_state})`).join('\n');try{await navigator.clipboard.writeText(value);notice.value='planCopied';}catch{copyText.value=value;}}
</script>
<template><section class="widget meal-planner"><div class="widget-title"><h2>{{t('planTitle')}}</h2><span class="chip">{{from}} — {{to}}</span></div><p>{{t('planIntro')}}</p><p v-if="isPublicDemo" class="widget-note">{{t('planDemo')}}</p><label>{{t('planWeek')}}<input v-model="from" type="date" required></label><form @submit.prevent="add"><label>{{t('planDate')}}<input v-model="date" type="date" min="2000-01-01" max="2099-12-31" required></label><label>{{t('planRecipe')}}<select v-model="recipe" required><option v-for="item in account.data?.recommendations??[]" :key="item.slug" :value="item.slug">{{recipeLabel(item.slug,locale,item.title)}}</option></select></label><label>{{t('planPortions')}}<input v-model.number="portions" type="number" min="1" max="20" step="1" required></label><button :disabled="pending||!recipe">{{t(pending?'loading':'planAdd')}}</button></form><p v-if="failure||store.error" class="error" role="alert">{{t(failure||'planningFailed')}}</p><p v-if="notice" class="success" role="status">{{t(notice)}}</p><p v-if="store.busy" role="status">{{t('loading')}}</p><ul v-else class="planned-meals"><li v-for="item in store.entries" :key="item.id"><div><strong>{{recipeLabel(item.recipe_slug,locale,item.title)}}</strong><small>{{item.planned_for}} · {{t('portions')}}: {{item.servings}}</small><RouterLink :to="{path:'/recipes',query:{recipe:item.recipe_slug,portions:item.servings}}">{{t('openRecipes')}} →</RouterLink></div><button :disabled="pending" @click="remove(item.id)" :aria-label="t('remove')+' '+recipeLabel(item.recipe_slug,locale,item.title)">{{t('remove')}}</button></li></ul><p v-if="!store.busy&&!store.entries.length">{{t('planEmpty')}}</p><p class="widget-note">{{t('planNoDiary')}}</p><h3>{{t('planShopping')}}</h3><ul class="shopping-items"><li v-for="item in store.shopping?.items??[]" :key="item.ingredient_id+'|'+item.preparation_state"><span>{{ingredientLabel(item.name,locale)}}<small>{{t(item.preparation_state==='raw'?'planStateRaw':item.preparation_state==='cooked'?'planStateCooked':'planStateUnknown')}}</small></span><strong>{{item.grams}} {{t('grams')}}</strong></li></ul><p v-if="!store.shopping?.items.length">{{t('planShoppingEmpty')}}</p><button v-else type="button" @click="copy">{{t('planCopy')}}</button><textarea v-if="copyText" :value="copyText" readonly :aria-label="t('planShopping')"></textarea></section></template>
